const d = msg.payload || {};
const object = d.object || {};
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
  gatewayId: object.gatewayId || 'gw-home-01',
  nodeId: object.nodeId || d.deviceInfo?.devEui || 'unknown-node',
  timestamp: d.time || new Date().toISOString(),
  frameCounter: object.frameCounter || 0,
  seqNo: object.seqNo || 0,
  rssi: d.rxInfo && d.rxInfo[0] ? d.rxInfo[0].rssi : null,
  snr: d.rxInfo && d.rxInfo[0] ? d.rxInfo[0].snr : null,
  battery: {
    voltage: object.batteryVoltage || 0,
    percentage: object.batteryPct || 0,
    lowBattery: !!object.lowBattery || (object.batteryPct !== undefined && object.batteryPct < 20)
  },
  measurements: object.measurements || [],
  rawPayloadHex: d.data || null,
  metadata: { devEui: d.deviceInfo?.devEui || null }
};
return msg;
